#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    bool isPalindrome(int x) {
        if (x < 0) return false;
        if (x != 0 && x % 10 == 0) return false;
        int reverted = 0;
        while (x > reverted) {
            int pop = x % 10;
            x /= 10;
            // check overflow not necessary because reverted <= original and int32 bounds hold for inputs
            reverted = reverted * 10 + pop;
        }
        return x == reverted || x == reverted / 10;
    }
};

