class Solution {
    public boolean isPalindrome(int x) {
        if (x < 0) return false;
        if (x != 0 && x % 10 == 0) return false;
        int reverted = 0;
        while (x > reverted) {
            int pop = x % 10;
            x /= 10;
            reverted = reverted * 10 + pop;
        }
        return x == reverted || x == reverted / 10;
    }
}

