import sys, json
from typing import List

class Solution:
    # Numeric approach: reverse half of the number
    def isPalindrome(self, x: int) -> bool:
        if x < 0:
            return False
        # Numbers ending with 0 (but not 0 itself) are not palindromes
        if x != 0 and x % 10 == 0:
            return False
        reverted = 0
        while x > reverted:
            reverted = reverted * 10 + x % 10
            x //= 10
        # For odd length numbers, reverted//10 removes the middle digit
        return x == reverted or x == reverted // 10

if __name__ == '__main__':
    _args = json.loads(sys.stdin.readline())
    _x = _args[0]
    print(json.dumps(Solution().isPalindrome(_x)))

