function isPalindrome(x) {
    if (x < 0) return false;
    if (x !== 0 && x % 10 === 0) return false;
    let reverted = 0;
    while (x > reverted) {
        reverted = reverted * 10 + x % 10;
        x = Math.trunc(x / 10);
    }
    return x === reverted || x === Math.trunc(reverted / 10);
}

